// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily: interFamily } = loadInter();



export type YearFlipProps = Record<string, any>;

const YearFlip: React.FC<YearFlipProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,
  textColor = "#ffffff",
  prefix = "20",
  startSuffix = 16,
  endSuffix = 26,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive layout calculations tailored for 9:16 vertical stack presence
  const shortestSide = Math.min(width, height);
  const casingWidth = shortestSide * 0.9;
  const casingHeight = casingWidth * 0.6;
  const cardBorderRadius = shortestSide * 0.03;
  // Adjusted font size to fit numbers neatly inside the rounded rectangular cards
  const fontSize = casingHeight * 0.55; 

  // Generate the array of numbers to flip through
  const items: number[] = [];
  const direction = startSuffix <= endSuffix ? 1 : -1;
  const count = Math.abs(endSuffix - startSuffix) + 1;
  
  for (let i = 0; i < count; i++) {
    items.push(startSuffix + i * direction);
  }

  // Animation Timings
  const totalFrames = durationInSeconds * fps;
  const holdStartFrames = Math.min(fps * 0.8, totalFrames * 0.2);
  const holdEndFrames = Math.min(fps * 1.5, totalFrames * 0.4);
  const rollDurationFrames = Math.max(1, totalFrames - holdStartFrames - holdEndFrames);
  const rollEndFrame = holdStartFrames + rollDurationFrames;

  // Physical split-flap roll progress (0 to max index)
  const rollProgress = interpolate(
    frame,
    [holdStartFrames, rollEndFrame],
    [0, count - 1],
    {
      easing: Easing.inOut(Easing.exp), // Realistic slow-fast-slow physical machine easing
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Calculate strict flap indices and fractional flip progress
  const safeProgress = Math.min(count - 1, Math.max(0, rollProgress));
  const currentIndex = Math.min(count - 2, Math.floor(safeProgress));
  const fraction = safeProgress - currentIndex;

  const currentSuffix = items[currentIndex].toString().padStart(2, "0");
  const nextSuffix = items[currentIndex + 1].toString().padStart(2, "0");

  // Subtle continuous cinematic zoom
  const globalScale = interpolate(frame, [0, totalFrames], [0.95, 1.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Shared Styles
  const cardBaseStyle: React.CSSProperties = {
    flex: 1,
    height: '100%',
    backgroundColor: '#121212',
    borderRadius: cardBorderRadius,
    position: 'relative',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    boxShadow: '0 10px 30px rgba(0,0,0,0.8)',
    perspective: '1500px', // Crucial for 3D split-flap effect
  };

  const textStyle: React.CSSProperties = {
    position: 'absolute',
    width: '100%',
    height: '100%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize,
    color: textColor,
    fontWeight: 900,
    fontVariantNumeric: "tabular-nums",
    letterSpacing: "-0.05em",
    lineHeight: 1,
    borderRadius: cardBorderRadius,
    backgroundColor: '#121212',
    backfaceVisibility: 'hidden',
  };

  const cardVignette = (
    <div style={{
      position: 'absolute',
      top: 0, left: 0, right: 0, bottom: 0,
      borderRadius: cardBorderRadius,
      boxShadow: 'inset 0 0 40px rgba(0,0,0,0.8)',
      zIndex: 20,
      pointerEvents: 'none'
    }} />
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: interFamily,
        transition: "none",
      }}
    >
      <div style={{ transform: `scale(${globalScale})`, transition: "none" }}>
        
        {/* Outer Machine Casing */}
        <div style={{
          width: casingWidth,
          height: casingHeight,
          backgroundColor: '#262626',
          borderRadius: cardBorderRadius * 1.5,
          padding: '4%',
          display: 'flex',
          gap: '4%',
          boxShadow: 'inset 0 4px 20px rgba(0,0,0,0.8), 0 25px 50px rgba(0,0,0,0.6)',
        }}>
          
          {/* Prefix Card (Static) */}
          <div style={cardBaseStyle}>
            <div style={textStyle}>
              {prefix}
            </div>
            {cardVignette}
          </div>

          {/* Suffix Card (Animated 3D Split Flap) */}
          <div style={cardBaseStyle}>
            
            {/* Base Top Half (Reveals Next Number) */}
            <div style={{ ...textStyle, clipPath: 'inset(0 0 50% 0)' }}>
              {nextSuffix}
            </div>

            {/* Base Bottom Half (Holds Current Number) */}
            <div style={{ ...textStyle, clipPath: 'inset(50% 0 0 0)' }}>
              {currentSuffix}
            </div>

            {/* Flap 1: Top half swinging down (Shows Current Number) */}
            {fraction < 0.5 && (
              <div style={{
                ...textStyle,
                clipPath: 'inset(0 0 50% 0)',
                transformOrigin: 'center center',
                transform: `rotateX(${fraction * -180}deg)`,
                zIndex: 5,
                // Shadows dynamically darken as it falls away from light
                filter: `brightness(${1 - fraction * 0.8})`
              }}>
                {currentSuffix}
              </div>
            )}

            {/* Flap 2: Bottom half landing (Shows Next Number) */}
            {fraction >= 0.5 && (
              <div style={{
                ...textStyle,
                clipPath: 'inset(50% 0 0 0)',
                transformOrigin: 'center center',
                transform: `rotateX(${90 - ((fraction - 0.5) * 180)}deg)`,
                zIndex: 5,
                // Brightens as it falls into place catching light
                filter: `brightness(${0.6 + (fraction - 0.5) * 0.8})`
              }}>
                {nextSuffix}
              </div>
            )}

            {cardVignette}
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default YearFlip;